window.VERBDATA=window.VERBDATA||{};VERBDATA["c2-mirae-kim-12"]={"level":"고등","grade":"공통영어2","pub":"미래엔(김)","school":"금천고·상당고·세광고","term":"2학기 중간고사","lessons":[{"name":"1과","parts":[{"name":"❶","title":"동물 보호에 대해 배울 수 있는 장소인 동물 생크추어리로의 자원봉사 여행","n":4,"hook":"동아리 회장인 글쓴이가 동물 생크추어리로 봉사 여행을 가기로 했대. 생크추어리는 구조되거나 다치거나 학대당한 동물들이 안전하게 사는 곳이야. 동아리 애들도 다 좋다고 해서 잔뜩 들뜬 채로 출발했어."},{"name":"❷","title":"시설 견학과 보호소 청소 및 동물들의 먹이 준비","n":9,"sub":"July 29, Monday","hook":"봉사 첫날, 생크추어리에 도착해서 직원 Jane이 시설을 쭉 구경시켜 줬대. 곰이랑 코끼리가 자유롭게 돌아다니는 걸 보고 감탄했지. 그러고는 청소도 하고 과일이랑 채소를 잘라서 먹이도 준비했는데, 이가 약한 할머니 코끼리한테는 사탕수수 대신 바나나를 잘라 줬대. 하루 종일 힘들었지만 보람 있었고 직원들의 정성에 감동받았어."},{"name":"❸","title":"아기 곰들의 본능 회복을 돕는 ‘행동 풍부화’ 활동","n":9,"sub":"July 30, Tuesday","hook":"둘째 날엔 아기 곰 Ben이랑 Lily를 위해 특별한 일을 했대. 얘네는 농장의 좁은 우리에서 불법으로 길러지다가 구조된 곰들이야. 곰이 본능을 되찾게 도와주려고 통나무에 구멍 뚫고 꿀을 채워서 나무에 걸어 줬어. 곰은 똑똑해서 자극이 없으면 지루해하고 스트레스 받거든. 잠시 뒤 곰들이 다가와서 꿀을 먹기 시작했는데 너무 귀여웠대."},{"name":"❹","title":"코끼리의 발 치료를 돕기 위한 긍정 행동 강화 훈련","n":7,"sub":"July 31, Wednesday","hook":"셋째 날엔 늙은 코끼리 Molly를 만났대. 25년 동안 관광객을 태우고 험한 길을 다닌 탓에 척추가 휘고 발이 아프대. 그래서 발을 치료하는 걸 돕는 훈련에 참여했어. 막대기로 발을 살짝 건드리며 '발'이라고 하면 발을 들어 올리고, 그러면 수박으로 보상해 주는 거야. 이렇게 하면 치료받을 때 스트레스가 줄고, Molly도 잘 적응하고 있대."},{"name":"❺-1","title":"부상을 당한 새들의 치료를 보조하고 돌보는 봉사 활동","n":5,"sub":"August 1, Thursday","hook":"마지막 날엔 갑자기 구조 센터에서 연락이 왔대. 더위에 탈수된 새들이 하늘에서 떨어져 실려 온 거야. 수의사가 치료하는 동안 글쓴이는 새들에게 물을 줬어. 이런 일이 해마다 일어난다는 걸 알고, 인간의 활동이 기후 변화를 거쳐 동물을 어떻게 해치는지 곰곰이 생각하게 됐대."},{"name":"❺-2","title":"봉사 활동 소감 및 이번 경험으로 얻은 교훈","n":5,"hook":"봉사를 마치고 동물들이랑 직원들한테 작별 인사를 하면서 이런 기회가 있어서 고맙다고 느꼈대. 동물을 존중하고 조심스럽게 대하는 게 얼마나 중요한지, 인간도 지구를 함께 쓰는 동물 중 하나일 뿐이라는 걸 깨달았어. 앞으로도 동물 복지를 위해 열심히 하겠다고 다짐했대."},{"name":"본문 외","title":"곰의 권리와 보호 (본문 외 지문)","n":9,"hook":"곰 얘기야. 곰은 여덟 종이 있고 사는 곳도 다 달라. 그런데 사람을 만나면 죽임을 당하는 일이 많대. 최악은 곰 쓸개즙 농장인데, 쓸개즙이 전통 약재로 비싸게 팔려서 곰을 불법으로 잡아 가두는 거야. 금지된 나라도 많은데 수요 때문에 계속되고 있대. 정부랑 단체들이 곰을 구조해 보호 구역으로 보내고 있고, 1978년 유네스코 선언 이후 동물권이 나아졌지만 아직 법 밖에서 보호받지 못하는 동물도 많대."}],"items":[{"ko":"우리 학교 동아리 Care for Animals의 회장으로서, 나는 우리 동아리 회원들을 위해 동물 생크추어리로 떠나는 자원봉사 여행을 준비했다.","en":"As the leader of our school club Care for Animals, I ___[organize] a volunteer trip to an animal sanctuary for my club members.","ans":["organized"],"part":0,"why":["과거(여행을 '준비했던' 일)"],"jj":[{"e":["As the leader of our school club Care for Animals,","I organized a volunteer trip","to an animal sanctuary","for my club members."],"k":["우리 학교 동아리 Care for Animals의 회장으로서","나는 자원봉사 여행을 준비했다","동물 생크추어리로 떠나는","내 동아리 회원들을 위해"]}]},{"ko":"동물 생크추어리는 구조되거나 부상을 입었거나 학대를 당한 동물들이 안전하고 보살핌을 받을 수 있는 환경에서 살 수 있는 특별한 장소이다.","en":"An animal sanctuary ___[be] a special place where ___[rescue], ___[injure], or ___[abuse] animals ___[can, live] in a safe and ___[care] environment.","ans":["is","rescued","injured","abused","can live","caring"],"part":0,"why":["현재 일반적 사실, 주어 단수","과거분사(구조'된' animals 수식)","과거분사(부상'당한') 병렬","과거분사(학대'당한') 병렬","조동사 can+동사원형","현재분사형 형용사(보살펴 주는 환경)"],"star":1,"jj":[{"e":["An animal sanctuary is a special place","where rescued, injured, or abused animals","can live in a safe and caring environment."],"k":["동물 생크추어리는 특별한 장소이다","구조되거나 부상을 입거나 학대당한 동물들이","안전하고 보살핌을 받는 환경에서 살 수 있는"]}]},{"ko":"동아리 회원 모두와 나는 생크추어리가 동물 보호에 대해 배울 수 있는 완벽한 장소가 될 것이라는 데 동의했다.","en":"All the club members and I ___[agree] that the sanctuary ___[will, be] the perfect place ___[learn] about animal care.","ans":["agreed","would be","to learn"],"part":0,"why":["과거(주절 시제 일치)","시제일치: will → would","형용사적 용법 to부정사(place 수식)"],"jj":[{"e":["All the club members and I agreed","that the sanctuary would be the perfect place","to learn about animal care."],"k":["동아리 회원 모두와 나는 동의했다","생크추어리가 완벽한 장소가 될 것이라는 데","동물 보호에 대해 배우기에"]}]},{"ko":"새로운 경험에 들떠서 우리는 봉사 활동을 떠났다.","en":"___[Excite] for a new experience, we ___[set] out ___[volunteer].","ans":["Excited","set","to volunteer"],"part":0,"why":["감정 분사구문(we가 '들뜬', 과거분사)","과거 set out(set-set-set)","부사적 용법 to부정사(목적)"],"jj":[{"e":["Excited for a new experience,","we set out to volunteer."],"k":["새로운 경험에 들떠서","우리는 봉사 활동을 하러 떠났다"]}]},{"ko":"우리 동아리는 Free Animals 생크추어리에 도착했다.","en":"Our club ___[arrive] at the Free Animals sanctuary.","ans":["arrived"],"part":1,"why":["과거(일지, 도착한 사건)"],"jj":[{"e":["Our club arrived at the Free Animals sanctuary."],"k":["우리 동아리는 Free Animals 생크추어리에 도착했다"]}]},{"ko":"동물들을 보살피는 일을 담당하는 직원인 Jane은 우리를 환한 웃음으로 맞아 주었고 우리에게 시설을 안내해 주었다.","en":"Jane, the staff member in charge of animal care, ___[welcome] us with a big smile and ___[give] us a tour of the facility.","ans":["welcomed","gave"],"part":1,"why":["과거, 주어 Jane","and 병렬 과거(welcomed와 같은 시제)"],"jj":[{"e":["Jane, the staff member in charge of animal care,","welcomed us with a big smile","and gave us a tour of the facility."],"k":["동물 보살핌을 담당하는 직원인 Jane은","우리를 환한 웃음으로 맞아 주었다","그리고 우리에게 시설을 안내해 주었다"]}]},{"ko":"넓은 벌판을 자유롭게 돌아다니는 곰과 코끼리를 보는 것은 정말 멋진 일이었다.","en":"It ___[be] ___[amaze] ___[see] bears and elephants ___[move] freely in a large field.","ans":["was","amazing","to see","moving"],"part":1,"why":["가주어 It, 과거","사물이 '놀라운' 현재분사형 감정형용사","진주어 to부정사","지각동사 see+O+현재분사(OC)"],"jj":[{"e":["It was amazing","to see bears and elephants","moving freely in a large field."],"k":["그것은 정말 멋진 일이었다","곰과 코끼리를 보는 것은","넓은 벌판에서 자유롭게 돌아다니는"]}]},{"ko":"오늘 우리의 임무에는 보호소를 청소하는 것과 동물들의 먹이를 준비하는 것이 포함되어 있었다.","en":"Our tasks for the day ___[include] ___[clean] the shelter and ___[prepare] food for the animals.","ans":["included","cleaning","preparing"],"part":1,"why":["과거, 주어 Our tasks(복수)","included의 목적어 동명사","and 병렬 동명사(cleaning과 대등)"],"jj":[{"e":["Our tasks for the day included","cleaning the shelter","and preparing food for the animals."],"k":["오늘 우리의 임무에는 포함되어 있었다","보호소를 청소하는 것이","그리고 동물들을 위해 먹이를 준비하는 것이"]}]},{"ko":"동물들의 서식지를 청소하는 동안 우리는 동물들에게 해를 입힐 만한 위험 요소가 있는지 확인했다.","en":"While ___[clean] the habitats, we ___[check] if there ___[be] any hazards that ___[can, harm] the animals.","ans":["cleaning","checked","were","could harm"],"part":1,"why":["접속사 While+현재분사(분사구문)","과거(주절)","if절 안 과거 복수(there were)","관계절 시제일치 can → could"],"star":1,"jj":[{"e":["While cleaning the habitats,","we checked","if there were any hazards","that could harm the animals."],"k":["서식지를 청소하는 동안","우리는 확인했다","위험 요소가 있는지","동물들에게 해를 입힐 수 있는"]}]},{"ko":"그러고 나서 과일과 채소를 자르고 그것들을 몇 개의 큰 바구니에 나눠 담으면서 먹이 준비하는 것을 도왔다.","en":"Then, we ___[help] ___[prepare] the food by ___[cut] up fruits and vegetables and ___[divide] them into several large baskets.","ans":["helped","prepare","cutting","dividing"],"part":1,"why":["과거 시제","help+(O)+동사원형(to 생략)","by+동명사","and 병렬 동명사(by 뒤)"],"jj":[{"e":["Then, we helped prepare the food","by cutting up fruits and vegetables","and dividing them into several large baskets."],"k":["그러고 나서 우리는 먹이를 준비하는 것을 도왔다","과일과 채소를 잘라서","그리고 그것들을 몇 개의 큰 바구니에 나눠 담으면서"]}]},{"ko":"이가 약한 나이 든 코끼리를 위해서는 코끼리가 보통 먹는 사탕수수 대신에 바나나를 잘라 두었다.","en":"For old elephants with weak teeth, we ___[chop] bananas instead of the sugarcane that they usually ___[eat].","ans":["chopped","eat"],"part":1,"why":["과거(주절)","관계절 현재 습관, 주어 they(복수)"],"jj":[{"e":["For old elephants with weak teeth,","we chopped bananas","instead of the sugarcane","that they usually eat."],"k":["이가 약한 나이 든 코끼리를 위해","우리는 바나나를 잘랐다","사탕수수 대신에","그들이 보통 먹는"]}]},{"ko":"동물들을 도우면서 하루를 보낸 것은 내게 멋진 경험이었다.","en":"___[Spend] the whole day ___[help] out with the animals ___[be] an incredible experience for me.","ans":["Spending","helping","was"],"part":1,"why":["동명사 주어(하루를 보낸 것)","spend+시간+동명사(helping)","동명사구 주어=단수, 과거"],"star":1,"jj":[{"e":["Spending the whole day","helping out with the animals","was an incredible experience for me."],"k":["하루 종일 보낸 것은","동물들을 도우면서","내게 멋진 경험이었다"]}]},{"ko":"그것은 보람 있는 경험이었고, 나는 직원들이 모든 동물에게 쏟는 애정에 감명받았다.","en":"It ___[be] a ___[reward] experience, and I ___[impress] with the attention the staff members ___[give] to all the animals.","ans":["was","rewarding","was impressed","gave"],"part":1,"why":["과거, 주어 It","경험이 '보람을 주는' 현재분사형","수동태(I가 '감명받은')","관계절(관계사 생략) 과거"],"jj":[{"e":["It was a rewarding experience,","and I was impressed","with the attention the staff members gave","to all the animals."],"k":["그것은 보람 있는 경험이었다","그리고 나는 감명받았다","직원들이 쏟는 애정에","모든 동물에게"]}]},{"ko":"오늘 우리는 Ben과 Lily를 위해 특별한 일을 했다.","en":"Today, we ___[do] something special for Ben and Lily.","ans":["did"],"part":2,"why":["과거(일지에서 오늘 한 일)"],"jj":[{"e":["Today, we did something special","for Ben and Lily."],"k":["오늘 우리는 특별한 일을 했다","Ben과 Lily를 위해"]}]},{"ko":"이 두 마리 아기 곰은 수년간 농장의 작은 우리 안에서 불법으로 사육된 후에 구조되었다.","en":"These two baby bears ___[rescue] after they ___[have, raise] illegally in a tiny cage on a farm for many years.","ans":["were rescued","had been raised"],"part":2,"why":["수동태 과거(곰이 '구조된')","과거완료 수동(구조 이전 사육됨)"],"star":1,"jj":[{"e":["These two baby bears were rescued","after they had been raised illegally","in a tiny cage on a farm","for many years."],"k":["이 두 마리 아기 곰은 구조되었다","불법으로 사육된 후에","농장의 작은 우리 안에서","수년 동안"]}]},{"ko":"곰들이 타고난 본능을 회복하는 것을 도와주기 위해, 우리는 '행동 풍부화'로 알려진 특별한 활동들을 시행했다.","en":"___[Help] the bears ___[restore] their natural instincts, we ___[carry] out some special activities ___[know] as “behavioral enrichment.”","ans":["To help","restore","carried","known"],"part":2,"why":["목적 to부정사(도와주기 위해)","help+O+동사원형(OC)","과거(carried out)","과거분사 후치수식(알려진 활동)"],"star":1,"jj":[{"e":["To help the bears restore their natural instincts,","we carried out some special activities","known as “behavioral enrichment.”"],"k":["곰들이 타고난 본능을 회복하도록 돕기 위해","우리는 몇몇 특별한 활동을 시행했다","“행동 풍부화”로 알려진"]}]},{"ko":"예를 들어, 우리는 곰을 위해 꿀이 든 통나무 먹이통을 만들었다.","en":"For example, we ___[make] honey-log feeders for the bears.","ans":["made"],"part":2,"why":["과거 시제"],"jj":[{"e":["For example, we made honey-log feeders","for the bears."],"k":["예를 들어 우리는 꿀이 든 통나무 먹이통을 만들었다","곰들을 위해"]}]},{"ko":"먼저, 통나무에 구멍을 몇 개 내고 그 안에 꿀을 채워 넣었다.","en":"First, we ___[make] several holes in a log and ___[fill] them with honey.","ans":["made","filled"],"part":2,"why":["과거 시제","and 병렬 과거"],"jj":[{"e":["First, we made several holes in a log","and filled them with honey."],"k":["먼저 우리는 통나무에 구멍을 몇 개 냈다","그리고 그것들을 꿀로 채웠다"]}]},{"ko":"그러고 나서 꿀이 든 통나무 먹이통을 곰들의 서식지 가까이 있는 나무에 걸어 두었다.","en":"Then, we ___[hang] the honey-log feeders on trees near the bears’ habitat.","ans":["hung"],"part":2,"why":["과거 불규칙(hang-hung)"],"jj":[{"e":["Then, we hung the honey-log feeders on trees","near the bears’ habitat."],"k":["그러고 나서 우리는 꿀이 든 통나무 먹이통을 나무에 걸었다","곰들의 서식지 가까이에"]}]},{"ko":"곰은 똑똑하고 호기심 많은 동물이라서 정신적 자극과 신체적 자극이 없으면 지루해하고 스트레스를 받을 수 있다.","en":"As bears ___[be] intelligent and curious creatures, they ___[can, become] ___[bore] and ___[stress] when ___[lack] mental and physical stimulation.","ans":["are","can become","bored","stressed","lacking"],"part":2,"why":["접속사 As절 현재, 주어 bears(복수)","조동사 can+동사원형","become+과거분사(지루해진)","and 병렬 과거분사","접속사 when+현재분사(분사구문)"],"jj":[{"e":["As bears are intelligent and curious creatures,","they can become bored and stressed","when lacking mental and physical stimulation."],"k":["곰은 똑똑하고 호기심 많은 동물이어서","그들은 지루해하고 스트레스를 받을 수 있다","정신적 자극과 신체적 자극이 부족할 때"]}]},{"ko":"꿀이 든 통나무 먹이통은 그들의 본능적인 호기심을 자극하고 그들을 야생에 있을 때만큼 활발함을 유지하도록 해준다.","en":"The honey-log feeders ___[stimulate] their natural curiosity and ___[keep] them as active as they ___[will, be] in the wild.","ans":["stimulate","keep","would be"],"part":2,"why":["현재, 주어 feeders(복수)","and 병렬 현재(stimulate와)","가정의 would(야생이라면 그랬을 정도)"],"star":1,"jj":[{"e":["The honey-log feeders stimulate their natural curiosity","and keep them as active","as they would be in the wild."],"k":["꿀이 든 통나무 먹이통은 그들의 타고난 호기심을 자극한다","그리고 그들을 활발하게 유지해 준다","야생에 있을 때만큼"]}]},{"ko":"잠시 후 Ben과 Lily는 먹이통으로 다가가서 그 안에 있는 꿀을 먹기 시작했다. 정말 귀여웠다!","en":"After a while, Ben and Lily ___[approach] the feeders and ___[start] ___[eat] the honey inside. They ___[be] so cute!","ans":["approached","started","eating","are"],"part":2,"why":["과거 시제","and 병렬 과거","start+동명사","현재 감탄, 주어 They(복수)"],"jj":[{"e":["After a while, Ben and Lily approached the feeders","and started eating the honey inside."],"k":["잠시 후 Ben과 Lily는 먹이통에 다가갔다","그리고 그 안에 있는 꿀을 먹기 시작했다"]},{"e":["They are so cute!"],"k":["그들은 정말 귀엽다"]}]},{"ko":"오늘 아침 우리는 나이 든 코끼리, Molly 덕분에 동물의 치료에 대해 배울 기회가 있었다.","en":"This morning, we ___[have] the opportunity ___[learn] about animal treatment thanks to Molly, an elderly elephant.","ans":["had","to learn"],"part":3,"why":["과거 시제","형용사적 to부정사(opportunity 수식)"],"jj":[{"e":["This morning, we had the opportunity","to learn about animal treatment","thanks to Molly, an elderly elephant."],"k":["오늘 아침 우리는 기회를 가졌다","동물의 치료에 대해 배울","나이 든 코끼리 Molly 덕분에"]}]},{"ko":"거친 길에서 25년간 관광객들을 실어 나른 후 Molly는 척추가 뒤틀리고 발에 통증이 생겼다.","en":"After ___[spend] 25 years ___[carry] tourists along rough roads, she ___[develop] a ___[twist] spine and foot pain.","ans":["spending","carrying","developed","twisted"],"part":3,"why":["전치사 After+동명사","spend+시간+동명사","과거 시제","과거분사 형용사(뒤틀린 척추)"],"jj":[{"e":["After spending 25 years","carrying tourists along rough roads,","she developed a twisted spine and foot pain."],"k":["25년을 보낸 후에","거친 길을 따라 관광객들을 실어 나르며","그녀(Molly)는 척추가 뒤틀리고 발에 통증이 생겼다"]}]},{"ko":"Molly의 발을 치료하는 Jane을 돕기 위해 우리는 긍정 행동 강화 훈련에 참여했는데, 그것은 바람직한 행동을 강화하는 데 보상을 이용하는 것을 포함한다.","en":"In order ___[support] Jane in ___[take] care of Molly’s foot, we ___[take] part in positive reinforcement training, which ___[involve] ___[use] rewards ___[encourage] desirable behaviors.","ans":["to support","taking","took","involves","using","to encourage"],"part":3,"why":["목적 in order+to부정사","전치사 in+동명사","과거(take part in)","관계대명사 which, 선행사 training(단수) 현재","involve의 목적어 동명사","목적 to부정사(강화하기 위해)"],"jj":[{"e":["In order to support Jane","in taking care of Molly’s foot,","we took part in positive reinforcement training,","which involves using rewards","to encourage desirable behaviors."],"k":["Jane을 돕기 위해","Molly의 발을 치료하는 데 있어","우리는 긍정 행동 강화 훈련에 참여했다","그것은(=훈련) 보상을 이용하는 것을 포함한다","바람직한 행동을 장려하기 위해"]}]},{"ko":"내가 막대기로 Molly의 발을 부드럽게 건드리면서 “발”이라고 말하면 Molly가 발을 들어 올렸다.","en":"When I gently ___[touch] her foot with a pole and ___[call] out, “foot,” she ___[lift] it.","ans":["touched","called","lifted"],"part":3,"why":["When절 과거","and 병렬 과거","과거(그때마다 든 동작)"],"jj":[{"e":["When I gently touched her foot with a pole","and called out, “foot,”","she lifted it."],"k":["내가 막대기로 그녀의 발을 부드럽게 건드리고","“발”이라고 외치면","그녀는 그것(발)을 들어 올렸다"]}]},{"ko":"그러면 우리는 Molly가 가장 좋아하는 과일인 달콤한 수박 한 조각을 보상으로 줬다.","en":"We then ___[reward] her with a sweet piece of watermelon, her favorite fruit.","ans":["rewarded"],"part":3,"why":["과거 시제"],"jj":[{"e":["We then rewarded her","with a sweet piece of watermelon,","her favorite fruit."],"k":["그러고 나서 우리는 그녀에게 보상을 주었다","달콤한 수박 한 조각으로","바로 그녀가 가장 좋아하는 과일"]}]},{"ko":"이 훈련은 동물이 치료나 건강 검진과 같이 통제된 상황 속에서 겪는 스트레스를 줄이는 데 도움을 준다.","en":"This training ___[help] ___[reduce] the stress that animals ___[experience] during ___[control] situations, such as treatment or a health examination.","ans":["helps","reduce","experience","controlled"],"part":3,"why":["현재, 주어 This training(단수)","help+동사원형(to 생략)","관계절 현재, 주어 animals(복수)","과거분사(통제'된' 상황, 수동)"],"star":1,"jj":[{"e":["This training helps reduce the stress","that animals experience","during controlled situations,","such as treatment or a health examination."],"k":["이 훈련은 스트레스를 줄이는 데 도움이 된다","동물들이 겪는","통제된 상황 동안","치료나 건강 검진과 같은"]}]},{"ko":"좋은 소식은 Molly가 잘 적응하고 있는 것처럼 보인다는 것이고 나는 Molly가 곧 더 나아질 것이라고 기대한다.","en":"The good news ___[be] Molly ___[seem] ___[be, adapt] well, and I ___[expect] her ___[get] better soon.","ans":["is","seems","to be adapting","expect","to get"],"part":3,"why":["현재, 주어 The good news(단수)","현재, 주어 Molly(3인칭 단수)","seem+to부정사 진행형(적응하는 중)","현재, 주어 I","expect+O+to부정사"],"star":1,"jj":[{"e":["The good news is","Molly seems to be adapting well,","and I expect her to get better soon."],"k":["좋은 소식은","Molly가 잘 적응하고 있는 것 같다는 것이다","그리고 나는 그녀가 곧 나아질 것이라고 기대한다"]}]},{"ko":"마지막 날에 우리는 갑작스러운 응급 상황 때문에 구조 센터로 불려 가게 되었다.","en":"On the last day, we ___[call] to the rescue center due to a sudden emergency.","ans":["were called"],"part":4,"why":["수동태 과거(우리가 '불려 간')"],"jj":[{"e":["On the last day,","we were called to the rescue center","due to a sudden emergency."],"k":["마지막 날에","우리는 구조 센터로 불려 갔다","갑작스러운 응급 상황 때문에"]}]},{"ko":"탈수 상태의 몇몇 새들이 도시의 하늘에서 떨어져서 센터로 이송되었다.","en":"Some ___[dehydrate] birds ___[have, fall] out of the sky in the city and ___[bring] to the center.","ans":["dehydrated","had fallen","were brought"],"part":4,"why":["과거분사(탈수'된' 새 수식)","과거완료(떨어진 게 이송보다 먼저)","수동 과거, A be brought to B"],"star":1,"jj":[{"e":["Some dehydrated birds had fallen out of the sky","in the city","and were brought to the center."],"k":["탈수 상태의 몇몇 새들이 하늘에서 떨어졌었다","도시에서","그리고 센터로 옮겨졌다"]}]},{"ko":"수의사가 새들의 부러진 날개와 다리를 치료하고 빠른 회복을 위해 그들에게 비타민을 주입하는 동안 우리는 수의사의 안내에 따르며 새들에게 물을 주었다.","en":"___[Follow] the veterinarian’s guidance, we ___[provide] water to the birds while the vets ___[treat] their ___[break] wings and legs and ___[inject] them with vitamins for a speedy recovery.","ans":["Following","provided","treated","broken","injected"],"part":4,"why":["분사구문 Following(we, 능동)","과거 시제","while절 과거, 주어 vets(복수)","과거분사(부러진 날개)","and 병렬 과거(treated와)"],"star":1,"jj":[{"e":["Following the veterinarian’s guidance,","we provided water to the birds","while the vets treated their broken wings and legs","and injected them with vitamins","for a speedy recovery."],"k":["수의사의 안내를 따라","우리는 새들에게 물을 주었다","수의사들이 새들의 부러진 날개와 다리를 치료하는 동안","그리고 새들에게 비타민을 주입하는 동안","빠른 회복을 위해"]}]},{"ko":"높은 기온이 도시의 수자원을 말려 버리기 때문에 이런 종류의 사건이 매해 일어나고 있다는 것은 충격이었다.","en":"It ___[be] ___[shock] that this type of accident ___[happen] every year since the high temperatures ___[dry] up water sources in the city.","ans":["was","shocking","happens","dry"],"part":4,"why":["가주어 It, 과거","사건이 '충격적인' 현재분사형","that절 현재(매해 반복), 주어 accident(단수)","since절 현재, 주어 temperatures(복수)"],"jj":[{"e":["It was shocking","that this type of accident happens every year","since the high temperatures dry up water sources in the city."],"k":["충격적이었다","이런 종류의 사고가 매년 일어난다는 것이","높은 기온이 도시의 수원을 말려 버리기 때문에"]}]},{"ko":"새들을 돌보면서 나는 인간의 활동이 기후 변화에 미치는 영향과 그것이 동물들에게 어떤 해를 끼치는지에 대해 깊이 생각해 볼 수밖에 없었다.","en":"___[Care] for the birds, I ___[can, not, help] but ___[reflect] on the impact of human activities on climate change and how it ___[harm] animals.","ans":["Caring","couldn’t help","reflect","harms"],"part":4,"why":["분사구문 Caring(I, 능동)","cannot help but(과거형)","but 뒤 동사원형","how절 현재, 주어 it(단수)"],"star":1,"jj":[{"e":["Caring for the birds,","I couldn’t help but reflect","on the impact of human activities on climate change","and how it harms animals."],"k":["새들을 돌보면서","나는 깊이 생각해 볼 수밖에 없었다","인간의 활동이 기후 변화에 미치는 영향에 대해","그리고 그것(=기후 변화)이 동물들에게 어떤 해를 끼치는지에 대해"]}]},{"ko":"동물들과 직원들에게 작별 인사를 하면서 나는 봉사 활동을 할 수 있었던 기회에 감사했다.","en":"___[Say] goodbye to the animals and staff, I ___[feel] grateful for the opportunity ___[volunteer].","ans":["Saying","felt","to volunteer"],"part":5,"why":["분사구문 Saying(I, 능동)","과거 시제","형용사적 to부정사(opportunity 수식)"],"jj":[{"e":["Saying goodbye to the animals and staff,","I felt grateful","for the opportunity to volunteer."],"k":["동물들과 직원들에게 작별 인사를 하면서","나는 감사함을 느꼈다","봉사 활동을 할 기회에"]}]},{"ko":"이번 경험을 통해 나는 동물들을 존중하면서 조심히 대하는 것의 중요성을 알게 되었다.","en":"From this experience, I ___[learn] the importance of ___[treat] animals with respect and care.","ans":["learned","treating"],"part":5,"why":["과거 시제","전치사 of+동명사"],"star":1,"jj":[{"e":["From this experience, I learned","the importance of treating animals","with respect and care."],"k":["이번 경험을 통해 나는 알게 되었다","동물들을 대하는 것의 중요성을","존중과 배려로"]}]},{"ko":"또한 인간은 동물의 또 다른 종일 뿐이며 다른 모든 생명체와 지구를 공유하고 있다는 것을 깨달았다.","en":"I also ___[come] ___[realize] that humans ___[be] just another kind of animal and ___[share] the Earth with all other ___[live] creatures.","ans":["came","to realize","are","share","living"],"part":5,"why":["과거, come to ~ (~하게 되다)","come to+동사원형","that절 현재(일반적 진리), 주어 humans(복수)","and 병렬 현재","현재분사형 형용사(살아 있는)"],"jj":[{"e":["I also came to realize","that humans are just another kind of animal","and share the Earth","with all other living creatures."],"k":["나는 또한 깨닫게 되었다","인간은 동물의 또 다른 종일 뿐이라는 것을","그리고 지구를 공유한다는 것을","다른 모든 생명체와"]}]},{"ko":"동물의 복지를 향상시키기 위해 나는 Care for Animals 회원들과 열심히 노력할 것이다.","en":"___[Improve] animal welfare, I ___[will, work] hard with Care for Animals members.","ans":["To improve","will work"],"part":5,"why":["목적 to부정사(향상시키기 위해)","미래 의지 will+동사원형"],"jj":[{"e":["To improve animal welfare,","I will work hard","with Care for Animals members."],"k":["동물 복지를 향상시키기 위해","나는 열심히 노력할 것이다","Care for Animals 회원들과 함께"]}]},{"ko":"바라건대 내년 여름에 또 다른 생크추어리에서 봉사 활동을 할 기회가 있다면 좋겠다.","en":"Hopefully, I ___[will, have] the chance ___[volunteer] at another sanctuary next summer.","ans":["will have","to volunteer"],"part":5,"why":["미래 will+동사원형","형용사적 to부정사(chance 수식)"],"jj":[{"e":["Hopefully, I will have the chance","to volunteer at another sanctuary","next summer."],"k":["바라건대 나는 기회를 갖게 되면 좋겠다","또 다른 생크추어리에서 봉사 활동을 할","내년 여름에"]}]},{"ko":"곰은 총 여덟 종이 있는 매력적인 동물 집단으로 그들은 모두 전 세계적으로 매우 다른 서식지에서 살고 있다.","en":"Bears ___[be] a ___[fascinate] group of animals with eight species, all ___[live] in very different habitats around the world.","ans":["are","fascinating","living"],"part":6,"why":["현재, 주어 Bears(복수)","현재분사형 형용사(매혹적인)","분사구문 all living(부대상황, 능동)"],"jj":[{"e":["Bears are a fascinating group of animals","with eight species,","all living in very different habitats","around the world."],"k":["곰은 매력적인 동물 집단이다","여덟 종을 가진","모두 매우 다른 서식지에서 살면서","전 세계에"]}]},{"ko":"예를 들어, 북극곰은 북극에서 사는 반면 안데스 곰은 남아메리카에 산다.","en":"Polar bears, for example, ___[live] in the Arctic, whereas Andean bears ___[live] in South America.","ans":["live","live"],"part":6,"why":["현재, 주어 Polar bears(복수)","whereas절 현재, 주어 Andean bears(복수)"],"jj":[{"e":["Polar bears, for example, live in the Arctic,","whereas Andean bears live in South America."],"k":["예를 들어 북극곰은 북극에서 산다","반면 안데스 곰은 남아메리카에서 산다"]}]},{"ko":"이 곰들은 살아갈 자유가 있어야 하지만 인간과 만나면 종종 죽임을 당한다.","en":"These bears ___[should, have] the freedom ___[live], but they ___[often, kill] when they ___[come] into contact with humans.","ans":["should have","to live","are often killed","come"],"part":6,"why":["should+have(당연·의무)","형용사적 to부정사(freedom 수식)","수동태 현재(곰이 '죽임당함')","when절 현재, 주어 they"],"star":1,"jj":[{"e":["These bears should have the freedom to live,","but they are often killed","when they come into contact with humans."],"k":["이 곰들은 살아갈 자유를 가져야 한다","하지만 그들은 종종 죽임을 당한다","인간과 접촉하게 되면"]}]},{"ko":"이 중 최악의 사례 하나는 곰 쓸개즙 농장이다.","en":"One of the worst examples of this ___[be] bear bile farming.","ans":["is"],"part":6,"why":["One of the+최상급+복수명사, 단수동사"],"jj":[{"e":["One of the worst examples of this","is bear bile farming."],"k":["이것(=곰이 죽임당하는 일) 중 최악의 사례 하나는","곰 쓸개즙 농장이다"]}]},{"ko":"유라시아와 북아메리카의 갈색곰, 동남아시아의 태양곰, 그리고 아시아의 반달가슴곰은 종종 쓸개즙을 얻기 위해 불법적으로 사냥 당하고 사육되는데, 쓸개즙은 아시아 전통 약재로 고가에 팔린다.","en":"Brown bears in Eurasia and North America, Sun bears in Southeast Asia, and Asiatic black bears in Asia ___[often, hunt] and ___[keep] illegally for their bile, which ___[be, sell] at a high price for traditional Asian medicine.","ans":["are often hunted","kept","is sold"],"part":6,"why":["수동태 현재(곰이 '사냥당함'), 주어 복수","and 병렬 과거분사(hunted와 대등)","관계절 수동 현재, 주어 bile(단수)"],"jj":[{"e":["Brown bears in Eurasia and North America,","Sun bears in Southeast Asia,","and Asiatic black bears in Asia","are often hunted and kept illegally","for their bile,","which is sold at a high price","for traditional Asian medicine."],"k":["유라시아와 북아메리카의 갈색곰","동남아시아의 태양곰","그리고 아시아의 반달가슴곰은","종종 사냥당하고 불법으로 사육된다","쓸개즙을 얻기 위해","그것은(=쓸개즙) 고가에 팔린다","아시아 전통 약재로"]}]},{"ko":"비록 여러 나라에서 쓸개 농장이 금지되어 있지만, 지속적인 수요 때문에 그것은 계속되고 있다.","en":"Although bile farming ___[prohibit] in many countries, it ___[continue] due to the constant demand.","ans":["is prohibited","continues"],"part":6,"why":["수동태 현재, 주어 bile farming(단수)","현재, 주어 it(단수)"],"jj":[{"e":["Although bile farming is prohibited in many countries,","it continues","due to the constant demand."],"k":["쓸개즙 농장이 여러 나라에서 금지되어 있지만","그것은 계속된다","지속적인 수요 때문에"]}]},{"ko":"정부와 동물 복지 단체는 이러한 농장을 찾아 곰을 구조하려는 시도를 지속적으로 하며, 그들이 곰 보호 구역이나 다른 안전한 장소에서 살 수 있게 한다.","en":"Governments and animal welfare organizations ___[make] persistent attempts ___[find] these farms and ___[rescue] the bears, ___[allow] them ___[live] in bear sanctuaries or other safe places.","ans":["make","to find","rescue","allowing","to live"],"part":6,"why":["현재, 주어 Governments and organizations(복수)","형용사적 to부정사(attempts 수식)","and 병렬 to부정사(to 생략)","분사구문 allowing(연속동작, 능동)","allow+O+to부정사"],"star":1,"jj":[{"e":["Governments and animal welfare organizations","make persistent attempts","to find these farms and rescue the bears,","allowing them to live","in bear sanctuaries or other safe places."],"k":["정부와 동물 복지 단체는","끈질긴 시도를 한다","이러한 농장을 찾아 곰을 구조하기 위해","그들(=곰)이 살 수 있게 하면서","곰 보호 구역이나 다른 안전한 장소에서"]}]},{"ko":"유네스코가 1978년에 동물도 존중받을 권리를 가지고 태어난다고 공표한 이후 동물권에 대한 진전이 이루어졌다.","en":"Since UNESCO ___[state] in 1978 that animals ___[bear] with the right ___[respect], progress ___[have, make] in animal rights.","ans":["stated","are born","to be respected","has been made"],"part":6,"why":["since절 과거(1978년 시점)","수동 be born with(태어나다), 현재 사실","형용사적 수동 to부정사(존중받을 권리)","since와 호응 현재완료 수동, 주어 progress(단수)"],"jj":[{"e":["Since UNESCO stated in 1978","that animals are born with the right to be respected,","progress has been made in animal rights."],"k":["유네스코가 1978년에 말한 이후로","동물은 존중받을 권리를 지니고 태어난다고","동물권에서 진전이 이루어졌다"]}]},{"ko":"그러나 일부 동물들은 여전히 법의 테두리 밖에서 완전히 보호받지 못하고 있으며 우리의 더 많은 관심과 보살핌을 필요로 한다.","en":"However, some animals ___[be] still not fully ___[protect] outside the law, and ___[need] more of our attention and care.","ans":["are","protected","need"],"part":6,"why":["현재, 주어 some animals(복수)","수동태(보호'받는'), be+과거분사","and 병렬 현재, 주어 animals(복수)"],"jj":[{"e":["However, some animals are still not fully protected","outside the law,","and need more of our attention and care."],"k":["그러나 일부 동물들은 여전히 완전히 보호받지 못한다","법의 테두리 밖에서","그리고 우리의 더 많은 관심과 보살핌이 필요하다"]}]}]},{"name":"2과","parts":[{"name":"❶","title":"다크 패턴의 사례를 보여주는 만화","n":3,"hook":"Tim이라는 애가 무료 영화 사이트에 가입했대. 근데 티셔츠 1달러 광고에 낚여서 배송비까지 16달러를 내게 돼. 그러고 무료 체험 취소하려다 버튼 문구에 낚여서 결국 자동 결제가 시작돼 버렸다는 얘기야."},{"name":"❷","title":"다크 패턴의 정의 & 유형 ① 강제 연속 결제","n":8,"hook":"'마지막 하나 남았어요!' 같은 말에 넘어가서 산 적 있냐고 묻는 걸로 시작해. 그게 바로 다크 패턴, 사용자를 속여서 원치 않는 결정을 하게 만드는 디자인이래. 대표적인 게 무료 체험 끝나면 몰래 돈을 받는 '강제 연속 결제'인데, 기업들이 일부러 종료를 안 알려주고 취소도 어렵게 만든대."},{"name":"❸","title":"다크 패턴의 유형 ② 숨겨진 비용 · ③ 수치심 유발 선택 강요","n":8,"hook":"다크 패턴이 또 있다는 얘기야. '숨겨진 비용'은 마지막 결제 단계에서 갑자기 배송비 같은 걸 얹어. 그리고 '수치심 유발 선택 강요'는 취소하려는 사람한테 '나는 혜택을 포기할래요' 같은 부끄러운 선택지를 보여줘서 구독을 유지하게 만든대."},{"name":"❹","title":"다크 패턴의 성장 원인 및 상충되는 견해","n":7,"hook":"그럼 다크 패턴은 왜 늘어나는 걸까? 스마트폰이 생기면서 온라인 쇼핑이 계속 커졌고, 경쟁이 심해지니까 기업들이 더 교활한 전략을 쓰기 시작했대. 기업은 그냥 새 마케팅이라고 하는데, 비평가들은 '진짜 마케팅은 기업이랑 고객 둘 다 이득이어야지, 이건 아니야'라고 맞서."},{"name":"❺","title":"다크 패턴 문제를 다루기 위한 연구·정부의 노력과 개개인의 태도","n":10,"hook":"다크 패턴은 고객을 조종할 뿐 아니라 돈 손해랑 개인정보 유출까지 부른대. 그래서 연구도 하고, EU 같은 데서는 법으로 금지도 했어. 그런데 법만으론 부족해서 우리도 조심해서 사고 약관도 읽고 기업 이익이 내 이익이 아닐 수 있다는 걸 알아야 한대."},{"name":"본문 외","title":"만평(Editorial cartoons)의 특징 (본문 외 지문)","n":9,"hook":"만평이 뭔지 알려주는 지문이야. 유머랑 과장으로 사회 문제를 슬쩍 꼬집어서 사람들이 얘기해 보게 만드는 그림이래. 인물 특징을 크게 그리고, 달러 기호나 뱀 같은 상징이랑 캡션을 써서 메시지를 전하는데, 다크 패턴 만화에서는 뱀이 기업이고 소비자가 그 먹잇감이 돼."}],"items":[{"ko":"#1: Tim은 새로운 스트리밍 사이트를 발견한다. / “오! 무료 영화다!” / (화면) 1주일 무료 / 체험 후 자동 갱신\n#2: 톡톡, 톡톡 / (화면) 가입하세요\n#3: 가입 신청서를 작성한 후… / (화면) 가입 완료! / 광고 / “아차! 잘못된 버튼을 눌렀나 봐. 그런데 이게 왜 여기에 있지?”","en":"#1: Tim ___[find] a new ___[stream] site. / “Wow! Free Movies!” / 1 WEEK FREE / Auto-Renewal After the Trial\n#2: Tap Tap, Tap Tap / ___[Join] Us\n#3: After ___[fill] out the form ... / ___[Sign] Up ___[Complete]! / AD / “Oops! I ___[must, have, press] the wrong button. But why ___[be] it here, anyway?!”","ans":["finds","streaming","Join","filling","Sign","Completed","must’ve pressed","is"],"part":0,"why":["주어 Tim(3단수) 현재형(만화 서술)","보통 site를 꾸미는 현재분사(스트리밍하는)","버튼 문구 명령문(동사원형)","after+~ing(전치사 뒤 동명사)","버튼 문구 명령문(동사원형)","완료 화면 표시 p.p.(가입이 '완료된')","must have p.p.(과거 추측)","주어 it(=that button) 3단수 현재"],"star":1},{"ko":"#4: “단돈 1달러? 엄청 싸네!” / (화면) 한정 특가\n#5: (화면) 지금 주문하세요 / 티셔츠 $1 / 배송비 $15 / 총계 $16 / “응…?”\n#6: “음, 여전히 괜찮은 가격이긴 해… 아마도…\n#7: 6일 후… / ”음… 이 웹사이트엔 좋은 영화가 없네. 구독을 취소하는 게 나을 것 같아.“","en":"#4: “Only 1 dollar?! What a deal!” / ___[Limit] Time Offer\n#5: ___[ORDER] NOW / T-shirt $1 / Delivery $15 / Total $16 / “Huh...?”\n#6: “Well, it ___[be] still a good price ... I ___[guess] ...\n#7: Six days later ... / “Uh... There ___[be] no good movies on this website. I’d better ___[cancel] my subscription.”","ans":["Limited","ORDER","is","guess","are","cancel"],"part":0,"why":["p.p. 형용사 '제한된'(한정 특가)","화면 버튼 명령문(동사원형)","주어 it 3단수 현재","I guess 주어 I 현재형","There are+복수 주어(good movies)","had better+동사원형"]},{"ko":"#8: (화면) 취소 요청 / 정말입니까? / 즐겁게 지낼래요 / 지루한 인생을 계속할래요 / 39초 후 무료 체험 종료 / “이봐! 내 인생은 지루하지 않아!”\n#9: (화면) 주문해 주셔서 감사합니다. / 자동 갱신이 지금 시작됩니다. / “안 돼!”","en":"#8: Cancellation Request / ___[Be] you sure? / ___[Stay] ___[Entertain] / ___[Continue] My ___[Bore] Life / Free trial ___[end] in 00:00:39 / “Hey! My life ___[not, be] ___[bore]!”\n#9: ___[Thank] you for your order. / Auto-Renewal ___[start] now. / “Noooo!!”","ans":["Are","Stay","Entertained","Continue","Boring","ends","isn’t","boring","Thank","starts"],"part":0,"why":["Are you ~? 의문문 be동사(주어 you)","버튼 명령문(동사원형)","감정 p.p.(주어가 즐거움을 '느끼는' 상태)","버튼 명령문(동사원형)","life 꾸미는 현재분사(지루하게 '하는')","주어 trial(단수) 현재형","현재 부정 be(My life isn't)","보어 자리 감정 분사(주어 life가 '지루하게 하는')","관용 표현 Thank you(동사원형 Thank)","주어 Renewal(단수) 현재형"]},{"ko":"‘서두르세요! 마지막 한 개 남았어요!’와 같은 메시지를 본 후 사려고 의도하지 않았음에도 불구하고 온라인에서 무언가를 구매한 적이 있는가?","en":"___[Have] you ever ___[buy] something online after ___[see] a message such as “Hurry! One item ___[leave]!” even though you ___[not, intend] ___[buy] it?","ans":["Have","bought","seeing","left","didn’t intend","to buy"],"part":1,"why":["현재완료 의문문(Have you ever ~?)","경험의 현재완료 p.p.(have you ever bought)","after+~ing(전치사 뒤 동명사)","message 꾸미는 문장 안 수동 p.p.(one item is left)","even though 절 과거 부정(didn't intend)","intend+to부정사(목적어)"],"star":1,"jj":[{"e":["Have you ever bought something online","after seeing a message","such as “Hurry! One item left!”","even though you didn’t intend to buy it?"],"k":["온라인에서 무언가를 구매한 적이 있는가","메시지를 본 후에","‘서두르세요! 마지막 한 개 남았어요!’와 같은","사려고 의도하지 않았음에도 불구하고"]}]},{"ko":"또는 기간 한정 특가 때문에 급하게 구매하게 되었다고 느낀 적이 있는가?","en":"Or ___[have] you ever ___[feel] ___[rush] into ___[make] a purchase because of a limited-time offer?","ans":["have","felt","rushed","making"],"part":1,"why":["현재완료 의문문(have you ever ~?)","경험 현재완료 p.p.(felt)","feel+보어(목적어 없는 2형식) p.p.(rushed, 급하게 '내몰린')","전치사 into 뒤 동명사"],"jj":[{"e":["Or have you ever felt rushed","into making a purchase","because of a limited-time offer?"],"k":["또는 서두르게 되었다고 느낀 적이 있는가","구매를 하도록","기간 한정 특가 때문에"]}]},{"ko":"만약 그렇다면, 당신은 다크 패턴의 희생물이 되었을 수도 있다.","en":"If you ___[have], then you ___[may, have, fall] prey to a dark pattern.","ans":["have","may have fallen"],"part":1,"why":["If you have (done so) 대동사 have, 현재완료 경험","may have p.p.(과거 추측 '~했을 수도')"],"star":1,"jj":[{"e":["If you have,","then you may have fallen prey","to a dark pattern."],"k":["만약 그렇다면","당신은 희생물이 되었을 수도 있다","다크 패턴의"]}]},{"ko":"다크 패턴은 사용자들을 속여 의도하지 않은 결정을 하게 만드는 웹사이트와 애플리케이션상의 교묘하게 (사용자들을) 조종하는 디자인이다.","en":"Dark patterns ___[be] manipulative designs on websites and applications that ___[trick] users into ___[make] unintended decisions.","ans":["are","trick","making"],"part":1,"why":["주어 Dark patterns(복수) 현재형","관계대명사 that 절, 선행사 designs(복수)→복수 동사","trick A into ~ing(전치사 뒤 동명사)"],"jj":[{"e":["Dark patterns are manipulative designs","on websites and applications","that trick users","into making unintended decisions."],"k":["다크 패턴은 교묘하게 조종하는 디자인이다","웹사이트와 애플리케이션상의","사용자들을 속여서","의도하지 않은 결정을 하도록"]}]},{"ko":"이러한 기만적인 관행은 종종 사용자들에게 재정적 손해를 초래하는 결과를 낳는다.","en":"These deceptive practices often ___[have] consequences that ___[cause] financial damages to the users.","ans":["have","cause"],"part":1,"why":["주어 practices(복수) 현재형","관계대명사 that절, 선행사 consequences(복수)→복수 동사"],"jj":[{"e":["These deceptive practices often have consequences","that cause financial damages","to the users."],"k":["이러한 기만적인 관행은 종종 결과를 갖는데","재정적 손해를 초래한다","사용자들에게"]}]},{"ko":"널리 사용되는 다크 패턴에는 ‘강제 연속 결제’라는 관행이 있고, 이것은 무료 체험이 끝난 후 사용자들에게 회원비를 지불하라고 요구한다.","en":"A widely ___[use] dark pattern ___[be] the practice of “___[force] continuity,” which ___[require] users ___[pay] a membership fee after a free trial ___[end].","ans":["used","is","forced","requires","to pay","ends"],"part":1,"why":["명사 dark pattern 꾸미는 과거분사(널리 '사용되는')","주어 pattern(단수) 현재형","practice를 꾸미는 p.p.(강요된 연속)","관계사 which절, 선행사 practice(단수)→3단수 -s","require+O+to부정사(목적격보어)","after 절 안 시간 부사절 현재형(주어 trial)"],"jj":[{"e":["A widely used dark pattern is the practice of “forced continuity,”","which requires users to pay a membership fee","after a free trial ends."],"k":["널리 사용되는 다크 패턴은 ‘강제 연속 결제’라는 관행이다","그리고 이것은(=그 관행) 사용자들에게 회원비를 지불하도록 요구한다","무료 체험이 끝난 후에"]}]},{"ko":"기업들은 고의로 사용자들에게 무료 체험 기간의 종료에 대해 알리는 것을 피하거나 취소 절차를 복잡하게 만든다.","en":"Companies deliberately ___[avoid] ___[inform] users about the end of the free trial period or ___[make] the cancellation process ___[complicate].","ans":["avoid","informing","make","complicated"],"part":1,"why":["주어 Companies(복수) 현재형","avoid+~ing(동명사만 목적어)","or 병렬: avoid ~ or make(주어 Companies)","make+O+p.p.(목적격보어, 절차가 '복잡해진')"],"jj":[{"e":["Companies deliberately avoid informing users","about the end of the free trial period","or make the cancellation process complicated."],"k":["기업들은 고의로 사용자들에게 알리는 것을 피한다","무료 체험 기간의 종료에 대해","또는 취소 절차를 복잡하게 만든다"]}]},{"ko":"그 결과, 사용자들은 더 이상 서비스를 이용하고 싶지 않더라도 회원비를 지불해야 한다.","en":"As a result, users ___[have to, pay] membership fees even if they no longer ___[want] ___[use] the service.","ans":["have to pay","want","to use"],"part":1,"why":["have to+동사원형(의무)","even if 절 주어 they 복수 현재형","want+to부정사(목적어)"],"jj":[{"e":["As a result, users have to pay membership fees","even if they no longer want to use the service."],"k":["그 결과 사용자들은 회원비를 지불해야 한다","더 이상 서비스를 이용하고 싶지 않더라도"]}]},{"ko":"또 다른 흔한 다크 패턴 유형은 ‘숨겨진 비용’으로 알려져 있다.","en":"Another common type of dark pattern ___[know] as “___[hide] fees.”","ans":["is known","hidden"],"part":2,"why":["수동태(is known as ~로 알려져 있다)","fees 꾸미는 p.p.(숨겨진 비용)"],"jj":[{"e":["Another common type of dark pattern","is known as “hidden fees.”"],"k":["또 다른 흔한 다크 패턴 유형은","‘숨겨진 비용’으로 알려져 있다"]}]},{"ko":"이 디자인은 주문 과정의 마지막 단계에서 갑자기 추가 요금을 부과한다.","en":"This design suddenly ___[add] extra fees at the last step of the ___[order] process.","ans":["adds","ordering"],"part":2,"why":["주어 design(단수) 현재형","process 앞 동명사(ordering process 주문 과정)"],"jj":[{"e":["This design suddenly adds extra fees","at the last step of the ordering process."],"k":["이 디자인은 갑자기 추가 요금을 부과한다","주문 과정의 마지막 단계에서"]}]},{"ko":"최종 페이지에서, 소비자들은 배송료나 처리 비용과 같이 판매자가 주문의 최종 금액을 증가시키기 위해 추가한 추가 요금을 발견하여 놀라게 된다.","en":"On the final page, consumers ___[surprise] ___[discover] additional charges, such as shipping or processing fees, which the seller ___[have, add] ___[increase] the final cost of the order.","ans":["are surprised","to discover","has added","to increase"],"part":2,"why":["수동태(감정: 소비자가 '놀란다')","감정 원인 to부정사(발견해서 놀라)","관계절 안 현재완료(the seller has added)","to부정사 목적(~하기 위해)"],"jj":[{"e":["On the final page,","consumers are surprised to discover additional charges,","such as shipping or processing fees,","which the seller has added","to increase the final cost of the order."],"k":["최종 페이지에서","소비자들은 추가 요금을 발견하고 놀란다","배송료나 처리 비용과 같은 요금들","이는(=추가 요금) 판매자가 추가한 것으로","주문의 최종 금액을 증가시키기 위해"]}]},{"ko":"‘수치심 유발 선택 강요’는 사용자가 알아야 할 또 다른 온라인 속임수이다.","en":"“Confirm-___[shame]” ___[be] another online trick that users ___[should, be] aware of.","ans":["shaming","is","should be"],"part":2,"why":["Confirm-shame+ing(명사적 이름)","주어 Confirm-shaming(단수) 현재형","that절 안 should be+형용사(aware of)"],"jj":[{"e":["“Confirm-shaming” is another online trick","that users should be aware of."],"k":["‘수치심 유발 선택 강요’는 또 다른 온라인 속임수인데","사용자들이 알아야 한다"]}]},{"ko":"이 기법은 사용자가 회원권을 취소하거나 주문에 대한 환불을 요청하는 것을 부끄럽다고 느끼도록 조종한다.","en":"This technique ___[manipulate] users into ___[feel] ashamed for ___[cancel] their membership or ___[request] a refund for an order.","ans":["manipulates","feeling","cancelling","requesting"],"part":2,"why":["주어 This technique(단수) 현재형","manipulate A into ~ing(전치사 뒤 동명사)","for+~ing(전치사 뒤 동명사)","or 병렬: cancelling ~ or requesting(동명사)"],"star":1,"jj":[{"e":["This technique manipulates users","into feeling ashamed","for cancelling their membership","or requesting a refund for an order."],"k":["이 기법은 사용자들을 조종한다","부끄럽다고 느끼도록","회원권을 취소하는 것에 대해","또는 주문에 대한 환불을 요청하는 것에 대해"]}]},{"ko":"기업들은 회원들의 의도와 다를지라도 회원들을 구독된 상태로 유지시키기 위해 이를 사용한다.","en":"Companies ___[use] this ___[keep] their members ___[subscribe], even if it ___[go] against the members’ intentions.","ans":["use","to keep","subscribed","goes"],"part":2,"why":["주어 Companies(복수) 현재형","to부정사 목적(~하기 위해)","keep+O+p.p.(목적어가 '구독된' 상태)","even if 절 주어 it 3단수 현재"],"star":1,"jj":[{"e":["Companies use this","to keep their members subscribed,","even if it goes against the members’ intentions."],"k":["기업들은 이것(=수치심 유발 선택 강요)을 사용한다","회원들을 구독된 상태로 유지시키기 위해","그것이 회원들의 의도에 반하더라도"]}]},{"ko":"예를 들어, 사용자가 구독을 취소하고 싶을 때 “나는 내 혜택을 유지하고 싶다”와 “나는 내 혜택을 포기하고 싶다”라는 두 가지 옵션이 제공된다.","en":"For example, when users ___[want] ___[cancel] their subscription, they ___[offer] two options: “I ___[want] ___[keep] my benefits” and “I ___[want] ___[give] up my benefits.”","ans":["want","to cancel","are offered","want","to keep","want","to give"],"part":2,"why":["when 절 주어 users(복수) 현재형","want+to부정사","수동태(사용자에게 옵션이 '제공된다')","주어 I 현재형(want)","want+to부정사","주어 I 현재형(want)","want+to부정사"],"jj":[{"e":["For example, when users want to cancel their subscription,","they are offered two options:","“I want to keep my benefits”","and “I want to give up my benefits.”"],"k":["예를 들어 사용자가 구독을 취소하고 싶을 때","두 가지 옵션이 제공된다","“나는 내 혜택을 유지하고 싶다”","그리고 “나는 내 혜택을 포기하고 싶다”"]}]},{"ko":"첫 번째 옵션은 매력적인 방식으로 제시되지만, 두 번째 옵션은 나쁜 선택처럼 보인다.","en":"The first option ___[present] in an ___[appeal] way, while the second option ___[seem] like a bad choice.","ans":["is presented","appealing","seems"],"part":2,"why":["수동태(옵션이 '제시된다') 단수","way 앞 형용사적 현재분사 appealing(매력적인)","주어 option(단수) 현재형"],"star":1,"jj":[{"e":["The first option is presented in an appealing way,","while the second option seems like a bad choice."],"k":["첫 번째 옵션은 매력적인 방식으로 제시된다","반면 두 번째 옵션은 나쁜 선택처럼 보인다"]}]},{"ko":"(신문) 다크 패턴: 속임수인가 마케팅 전략인가? 기업과 비평가들은 이 문제에 대해 상반된 견해를 가지고 있다. (만평) 안 돼! 또야! 결제 버튼을 눌러 버렸어! / 고마워, Steve… 나의 특별하고 교활한 다크 패턴 중 하나…","en":"Dark Patterns: Deception or Marketing Strategy?\nCompanies and critics ___[hold] ___[conflict] views on this issue.\nNo! Not again! I ___[hit] the payment button! / Sss... ___[thank] you, Sssteve... One of my ssspecial, sssneaky dark patterns... sss...","ans":["hold","conflicting","hit","thank"],"part":3,"why":["주어 Companies and critics(복수) 현재형","views 꾸미는 현재분사(상반된)","과거(결제 버튼을 이미 눌러 버린 일, hit-hit-hit 형태 동일)","Thank you 관용 표현(동사원형 Thank)"]},{"ko":"디지털 플랫폼에서의 다크 패턴이 더 복잡해지고 더 널리 퍼지고 있다.","en":"Dark patterns on digital platforms ___[be, become] more complex and more prevalent.","ans":["are becoming"],"part":3,"why":["현재진행(is/are becoming), 주어 patterns(복수)"],"jj":[{"e":["Dark patterns on digital platforms","are becoming more complex and more prevalent."],"k":["디지털 플랫폼에서의 다크 패턴은","더 복잡해지고 더 널리 퍼지고 있다"]}]},{"ko":"그렇다면, 무엇이 그 성장을 추진하고 있는가?","en":"So, what ___[be, drive] their growth?","ans":["is driving"],"part":3,"why":["현재진행 의문문(주어 what 3단수)"],"jj":[{"e":["So, what is driving their growth?"],"k":["그렇다면 무엇이 그 성장을 추진하고 있는가"]}]},{"ko":"지난 몇 년 동안, 온라인 상업은 특히 스마트폰과 다른 디지털 기술의 발전과 함께 꾸준히 성장해 왔다.","en":"Over the years, online commerce ___[have, grow] steadily, especially with the development of smart phones and other digital technologies.","ans":["has grown"],"part":3,"why":["현재완료(Over the years, 지금까지 계속)"],"jj":[{"e":["Over the years,","online commerce has grown steadily,","especially with the development","of smart phones and other digital technologies."],"k":["지난 몇 년 동안","온라인 상업은 꾸준히 성장해 왔다","특히 발전과 함께","스마트폰과 다른 디지털 기술의"]}]},{"ko":"온라인 시장의 경쟁이 심해짐에 따라, 기업들은 사람들을 속여서 구매하게 하는 더 교활한 전략을 개발하기 시작했다.","en":"As the competition in online markets ___[have, intensify], companies ___[have, begin] ___[develop] sneakier strategies ___[trick] people into ___[make] purchases.","ans":["has intensified","have begun","to develop","to trick","making"],"part":3,"why":["as 절 현재완료(경쟁이 '심해져 온')","주어 companies(복수) 현재완료","begin+to부정사","strategies 꾸미는 to부정사(형용사적 용법)","trick A into ~ing(전치사 뒤 동명사)"],"jj":[{"e":["As the competition in online markets has intensified,","companies have begun to develop sneakier strategies","to trick people into making purchases."],"k":["온라인 시장의 경쟁이 심해짐에 따라","기업들은 더 교활한 전략을 개발하기 시작했다","사람들을 속여서 구매하도록 하기 위해"]}]},{"ko":"이런 기업들은 그저 자신들이 새로운 유형의 마케팅 전략을 사용하고 있다고 주장하지만, 비평가들은 다크 패턴이 유효한 마케팅 전략이라는 데 동의하지 않는다.","en":"While these companies ___[insist] that they ___[be] simply ___[use] new types of marketing strategies, critics ___[not, agree] that dark patterns ___[be] valid marketing strategies.","ans":["insist","are","using","do not agree","are"],"part":3,"why":["While 절 주어 companies(복수) 현재형","that절 주어 they(복수) be(are)","현재진행(are using) 진행형","주어 critics(복수) 현재 부정(do not)","that절 주어 dark patterns(복수) be"],"star":1,"jj":[{"e":["While these companies insist","that they are simply using new types of marketing strategies,","critics do not agree","that dark patterns are valid marketing strategies."],"k":["이런 기업들이 주장하는 반면","자신들이 그저 새로운 유형의 마케팅 전략을 사용하고 있다고","비평가들은 동의하지 않는다","다크 패턴이 유효한 마케팅 전략이라는 데"]}]},{"ko":"오히려, 그들은 진정한 마케팅 전략은 기업과 고객 양측에 가치를 창출하고, 긍정적이고 지지적인 관계를 촉진해야 한다고 제안한다.","en":"Rather, they ___[suggest] that a real marketing strategy ___[create] value for both companies and customers, ___[promote] positive and supportive relationships.","ans":["suggest","create","promoting"],"part":3,"why":["주어 they(복수) 현재형","that절 주어 strategy(단수) 원형(제안 동사 뒤 should 생략)","분사구문(부대상황 '~하면서')"],"star":1,"jj":[{"e":["Rather, they suggest","that a real marketing strategy create value","for both companies and customers,","promoting positive and supportive relationships."],"k":["오히려 그들(=비평가들)은 제안한다","진정한 마케팅 전략은 가치를 창출해야 한다고","기업과 고객 양측에","긍정적이고 지지적인 관계를 촉진하면서"]}]},{"ko":"반면, 다크 패턴은 고객들이 그들의 의도에 반하여 행동하도록 조종할 뿐만 아니라, 경제적 손실과 개인 정보 유출로 이어질 수도 있다.","en":"Dark patterns, in contrast, not only ___[manipulate] customers ___[act] against their intentions, but they ___[can, also, lead] to financial losses and personal data leaks.","ans":["manipulate","to act","can also lead"],"part":4,"why":["not only A but also B, 주어 dark patterns 복수 현재","manipulate+O+to부정사(목적격보어)","조동사 can+원형(also 위치 주의)"],"star":1,"jj":[{"e":["Dark patterns, in contrast,","not only manipulate customers","to act against their intentions,","but they can also lead","to financial losses and personal data leaks."],"k":["반면 다크 패턴은","고객들을 조종할 뿐만 아니라","그들의 의도에 반하여 행동하도록","그것들은 또한 이어질 수도 있다","경제적 손실과 개인 정보 유출로"]}]},{"ko":"이 문제를 다루기 위해, 다양한 웹사이트와 애플리케이션에서의 광범위한 연구가 다크 패턴의 확산을 기록하고 해결책을 고안하기 위해 진행되고 있다.","en":"___[Tackle] this problem, extensive research across various websites and applications ___[be, be, conduct] ___[document] the prevalence of dark patterns and ___[come] up with solutions.","ans":["To tackle","is being conducted","to document","come"],"part":4,"why":["To tackle(목적 to부정사 '~하기 위해')","현재진행 수동(is being conducted)","목적 to부정사 to document","and 병렬 to부정사(to 생략)"],"star":1,"jj":[{"e":["To tackle this problem,","extensive research across various websites and applications","is being conducted","to document the prevalence of dark patterns","and come up with solutions."],"k":["이 문제를 다루기 위해","다양한 웹사이트와 애플리케이션에 걸친 광범위한 연구가","진행되고 있다","다크 패턴의 확산을 기록하기 위해","그리고 해결책을 고안하기 위해"]}]},{"ko":"연구뿐만 아니라, 정부들은 이러한 기만적인 디자인 패턴을 규제하는 방법에 대해 적극적으로 논의하고 있다.","en":"In addition to research, governments ___[be, actively, discuss] how ___[regulate] these deceptive design patterns.","ans":["are actively discussing","to regulate"],"part":4,"why":["현재진행(주어 governments 복수)","의문사+to부정사(how to regulate)"],"jj":[{"e":["In addition to research,","governments are actively discussing","how to regulate these deceptive design patterns."],"k":["연구뿐만 아니라","정부들은 적극적으로 논의하고 있다","이러한 기만적인 디자인 패턴을 규제하는 방법에 대해"]}]},{"ko":"2022년에 온라인 플랫폼에서 다크 패턴을 금지한 EU의 Digital Service Act(디지털 서비스법)는 이 분야에서의 그러한 규제의 좋은 예이다.","en":"The EU’s Digital Service Act, which ___[ban] dark patterns on online platforms in 2022, ___[be] a good example of such regulation in this area.","ans":["banned","is"],"part":4,"why":["관계절 안 과거(in 2022)","주어 Act(단수), 삽입 관계사절 뒤 is"],"jj":[{"e":["The EU’s Digital Service Act,","which banned dark patterns on online platforms in 2022,","is a good example of such regulation","in this area."],"k":["EU의 Digital Service Act(디지털 서비스법)는","2022년에 온라인 플랫폼에서 다크 패턴을 금지했는데","그러한 규제의 좋은 예이다","이 분야에서"]}]},{"ko":"이러한 규제는 디지털 시장에서 기업들의 기만적인 마케팅 관행을 제한하며 증가할 것으로 기대된다.","en":"Such regulations ___[expect] ___[increase], ___[limit] companies’ deceptive marketing practices in the digital market.","ans":["are expected","to increase","limiting"],"part":4,"why":["수동태 be expected(주어 regulations 복수)","expect+to부정사(수동 뒤 to부정사)","분사구문(부대상황 '제한하며')"],"jj":[{"e":["Such regulations are expected to increase,","limiting companies’ deceptive marketing practices","in the digital market."],"k":["이러한 규제는 증가할 것으로 기대된다","기업들의 기만적인 마케팅 관행을 제한하면서","디지털 시장에서"]}]},{"ko":"그러나 규제만으로는 충분하지 않을 수 있다.","en":"However, regulations alone ___[may, not, be] sufficient.","ans":["may not be"],"part":4,"why":["조동사 may+not+be(약한 추측)"],"jj":[{"e":["However, regulations alone may not be sufficient."],"k":["그러나 규제만으로는 충분하지 않을 수 있다"]}]},{"ko":"개인으로서, 우리는 다크 패턴과 싸우기 위해 조치를 취하고 우리의 온라인 쇼핑 행동에 책임을 져야 한다.","en":"As individuals, we ___[should, take] steps ___[combat] dark patterns and ___[be] responsible for our online shopping behavior.","ans":["should take","to combat","be"],"part":4,"why":["조동사 should+동사원형(의무)","steps 꾸미는 to부정사(~할 조치)","and 병렬: should take ~ and (should) be"],"jj":[{"e":["As individuals, we should take steps","to combat dark patterns","and be responsible for our online shopping behavior."],"k":["개인으로서 우리는 조치를 취해야 한다","다크 패턴과 싸우기 위해","그리고 우리의 온라인 쇼핑 행동에 책임을 져야 한다"]}]},{"ko":"이는 구매 시 주의를 기울이고, 약관을 주의 깊게 읽으며, 기업의 이익이 우리의 이익과 같지 않을 수 있다는 사실을 인식하는 것을 포함한다.","en":"This ___[include] ___[be] cautious while ___[make] purchases, ___[read] terms and conditions carefully, and ___[recognize] that companies’ interests ___[may, not, be] the same as our own.","ans":["includes","being","making","reading","recognizing","may not be"],"part":4,"why":["주어 This(단수) 현재형","include+~ing(동명사 목적어), be의 동명사형","while+~ing(접속사 뒤 분사구문)","병렬 동명사(being/reading/recognizing)","병렬 동명사(being/reading/recognizing)","that절 안 조동사 may not be"],"star":1,"jj":[{"e":["This includes being cautious while making purchases,","reading terms and conditions carefully,","and recognizing","that companies’ interests may not be the same as our own."],"k":["이것은 구매할 때 주의하는 것을 포함한다","약관을 주의 깊게 읽는 것","그리고 인식하는 것","기업의 이익이 우리의 이익과 같지 않을 수 있다는 점을"]}]},{"ko":"다크 패턴에 대한 인식을 발달시키는 것도 잠재적인 피해와 경제적 손실을 피하기 위해 필수적이다.","en":"___[Develop] an awareness of dark patterns ___[be] also essential ___[avoid] potential harm and economic loss.","ans":["Developing","is","to avoid"],"part":4,"why":["동명사 주어(Developing ~)","동명사구 주어(단수 취급) → is","essential 뒤 목적 to부정사(~하기 위해)"],"jj":[{"e":["Developing an awareness of dark patterns","is also essential","to avoid potential harm and economic loss."],"k":["다크 패턴에 대한 인식을 발달시키는 것도","필수적이다","잠재적인 피해와 경제적 손실을 피하기 위해"]}]},{"ko":"궁극적으로, 우리의 주의와 노력은 우리를 조작으로부터 보호하고 이 디지털 시대에 우리가 현명한 결정을 내릴 수 있게 할 것이다.","en":"Ultimately, our attention and efforts ___[will, protect] us from manipulation and ___[enable] us ___[make] wise decisions in this digital age.","ans":["will protect","enable","to make"],"part":4,"why":["조동사 will+동사원형(미래)","and 병렬: will protect ~ and enable(will 공유)","enable+O+to부정사(목적격보어)"],"jj":[{"e":["Ultimately, our attention and efforts will protect us","from manipulation","and enable us to make wise decisions","in this digital age."],"k":["궁극적으로 우리의 주의와 노력은 우리를 보호할 것이다","조작으로부터","그리고 우리가 현명한 결정을 내릴 수 있게 할 것이다","이 디지털 시대에"]}]},{"ko":"만평은 사회적, 정치적 또는 문화적 문제에 대한 관습적인 사고에 이의를 제기하기 위해 유머와 과장을 이용하는 시각 예술의 한 종류이다.","en":"Editorial cartoons ___[be] a type of visual art that ___[employ] humor and exaggeration ___[challenge] conventional thinking about social, political, or cultural issues.","ans":["are","employs","to challenge"],"part":5,"why":["주어 cartoons(복수) be동사 현재","관계대명사 that절, 선행사 art(단수)→3단수 -s","목적 to부정사(~하기 위해)"],"star":1,"jj":[{"e":["Editorial cartoons are a type of visual art","that employs humor and exaggeration","to challenge conventional thinking","about social, political, or cultural issues."],"k":["만평은 시각 예술의 한 종류이다","그것은(=시각 예술) 유머와 과장을 이용한다","관습적인 사고에 이의를 제기하기 위해","사회적, 정치적 또는 문화적 문제에 대한"]}]},{"ko":"겉보기에는 익살스럽지만, 만평의 진정한 목적은 사회적으로 중요한 문제에 대한 토의를 활성화시키는 것이다.","en":"Despite their humorous appearance, their true purpose ___[be] ___[promote] discussion about socially significant issues.","ans":["is","to promote"],"part":5,"why":["주어 purpose(단수) be동사 현재","be+to부정사 보어(목적 '~하는 것')"],"jj":[{"e":["Despite their humorous appearance,","their true purpose is to promote discussion","about socially significant issues."],"k":["겉보기에는 익살스럽지만","만평의 진정한 목적은 토의를 활성화시키는 것이다","사회적으로 중요한 문제에 대한"]}]},{"ko":"이를 달성하기 위해, 만화 작가들은 종종 공인이나 정치인을 포함한 인물들의 독특한 신체적 특성을 강조하거나 과장하여 유머를 만든다.","en":"___[Achieve] this, cartoonists often ___[emphasize] or ___[exaggerate] unique physical features of characters, including public or political figures, ___[create] humor.","ans":["To achieve","emphasize","exaggerate","to create"],"part":5,"why":["목적 to부정사(To achieve this)","주어 cartoonists 복수 현재형(often)","or 병렬 동사(emphasize or exaggerate)","목적 to부정사(유머를 만들기 위해)"],"jj":[{"e":["To achieve this,","cartoonists often emphasize or exaggerate","unique physical features of characters,","including public or political figures,","to create humor."],"k":["이를 달성하기 위해","만화 작가들은 종종 강조하거나 과장한다","인물들의 독특한 신체적 특성을","공인이나 정치인을 포함해서","유머를 만들기 위해"]}]},{"ko":"상징도 중요한 개념이나 생각을 나타내기 위해 사용된다.","en":"Symbols ___[also, use] ___[represent] important concepts or ideas.","ans":["are also used","to represent"],"part":5,"why":["수동태(현재, 주어 Symbols 복수)","목적 to부정사(~하기 위해)"],"jj":[{"e":["Symbols are also used","to represent important concepts or ideas."],"k":["상징도 사용된다","중요한 개념이나 생각을 나타내기 위해"]}]},{"ko":"예를 들어, 달러 기호는 돈을 상징할 수 있고, 벽은 분열을 나타낼 수 있으며, 뱀은 아마 속임수와 관련이 있을 것이다.","en":"For instance, a dollar sign ___[may, signify] money, a wall could ___[represent] division, and a snake probably ___[relate] to deception.","ans":["may signify","represent","relates"],"part":5,"why":["조동사 may+원형(추측)","조동사 could 뒤 동사원형","주어 snake(단수) 현재형 -s"],"jj":[{"e":["For instance, a dollar sign may signify money,","a wall could represent division,","and a snake probably relates to deception."],"k":["예를 들어 달러 기호는 돈을 상징할 수 있다","벽은 분열을 나타낼 수 있다","그리고 뱀은 아마 속임수와 관련이 있을 것이다"]}]},{"ko":"그림 위나 아래에 쓰여진 단어들인 캡션은 만화 작가의 메시지를 더 명료하게 한다.","en":"Captions, groups of words ___[write] on or below pictures, further ___[clarify] the cartoonist’s message.","ans":["written","clarify"],"part":5,"why":["groups를 꾸미는 과거분사(쓰여진)","주어 Captions(복수) 현재형"],"jj":[{"e":["Captions,","groups of words written on or below pictures,","further clarify the cartoonist’s message."],"k":["캡션은","그림 위나 아래에 쓰여진 단어들로서","만화 작가의 메시지를 더 명료하게 한다"]}]},{"ko":"한 주목할 만한 예는 Clifford Berryman이 1912년 미국 대통령 후보 세 명의 감정을 전달하기 위해 인물들과 캡션을 능숙하게 사용한 것이다.","en":"A notable example ___[be] Clifford Berryman’s skillful use of characters and captions ___[convey] the emotions of the three U.S. presidential candidates in 1912.","ans":["is","to convey"],"part":5,"why":["주어 example(단수) be동사 현재","목적 to부정사(전달하기 위한)"],"jj":[{"e":["A notable example","is Clifford Berryman’s skillful use of characters and captions","to convey the emotions","of the three U.S. presidential candidates in 1912."],"k":["한 주목할 만한 예는","Clifford Berryman이 인물들과 캡션을 능숙하게 사용한 것이다","감정을 전달하기 위해","1912년 미국 대통령 후보 세 명의"]}]},{"ko":"이는 그들의 외면적인 자신감과 실제 불안 사이의 대비를 강조한다.","en":"This ___[highlight] the contrast between their external confidence and their actual anxiety.","ans":["highlights"],"part":5,"why":["주어 This(단수) 현재형 -s"],"jj":[{"e":["This highlights the contrast","between their external confidence and their actual anxiety."],"k":["이것은(=앞의 사례) 대비를 강조한다","그들의 외면적인 자신감과 실제 불안 사이의"]}]},{"ko":"마찬가지로, 다크 패턴을 비판하는 만화에서는 상징과 캡션이 뱀으로 상징되는 기업의 조종적인 관행에 희생물이 되는 소비자를 효과적으로 묘사한다.","en":"Similarly, in the cartoon ___[criticize] dark patterns, symbols and captions effectively ___[depict] consumers ___[fall] prey to the manipulative practices of companies, ___[symbolize] by a snake.","ans":["criticizing","depict","falling","symbolized"],"part":5,"why":["cartoon 꾸미는 현재분사(비판하는)","주어 symbols and captions(복수) 현재형","묘사 지각 O+~ing(depict O falling)","practices 꾸미는 과거분사(상징되는)"],"jj":[{"e":["Similarly, in the cartoon criticizing dark patterns,","symbols and captions effectively depict consumers","falling prey to the manipulative practices of companies,","symbolized by a snake."],"k":["마찬가지로 다크 패턴을 비판하는 만화에서는","상징과 캡션이 소비자들을 효과적으로 묘사한다","기업의 조종적인 관행에 희생물이 되면서","뱀으로 상징되는"]}]}]}]};
